int libvarpd_plugin_load ( varpd_handle_t * vph , const char * path ) { int ret = 0 ; varpd_impl_t * vip = ( varpd_impl_t * ) vph ; mutex_enter ( & varpd_load_lock ) ; while ( varpd_load_handle != NULL ) { ( void ) cond_wait ( & varpd_load_cv , & varpd_load_lock ) ; } varpd_load_handle = vip ; mutex_exit ( & varpd_load_lock ) ; ret = libvarpd_dirwalk ( vip , path , ".so" , libvarpd_plugin_load_cb , NULL ) ; mutex_enter ( & varpd_load_lock ) ; varpd_load_handle = NULL ; ( void ) cond_signal ( & varpd_load_cv ) ; mutex_exit ( & varpd_load_lock ) ; return ( ret ) ; } 